-- Table: airlines
CREATE TABLE airlines (
    airline_id INTEGER PRIMARY KEY,
    airline_name TEXT NOT NULL,
    iata_code TEXT UNIQUE,
    icao_code TEXT UNIQUE,
    founded_date TEXT,
    hub_airport_code TEXT,
    is_active INTEGER DEFAULT 1
);

-- Table: fleet
CREATE TABLE fleet (
    aircraft_id INTEGER PRIMARY KEY,
    tail_number TEXT UNIQUE NOT NULL,
    model_name TEXT,
    manufacturer TEXT,
    year_manufactured INTEGER,
    max_range_km REAL,
    airline_id INTEGER,
    status TEXT CHECK (status IN ('ACTIVE', 'MAINTENANCE', 'STORED', 'RETIRED')),
    FOREIGN KEY (airline_id) REFERENCES airlines(airline_id)
);

-- Table: crew
CREATE TABLE crew (
    crew_id INTEGER PRIMARY KEY,
    employee_number TEXT UNIQUE NOT NULL,
    first_name TEXT,
    last_name TEXT,
    role TEXT CHECK (role IN ('CAPTAIN', 'FIRST_OFFICER', 'PURSER', 'FLIGHT_ATTENDANT', 'FLIGHT_ENGINEER')),
    license_expiry TEXT,
    base_id INTEGER,
    hire_date TEXT,
    FOREIGN KEY (base_id) REFERENCES airlines(airline_id)
);

-- Table: routes
CREATE TABLE routes (
    route_id INTEGER PRIMARY KEY,
    origin_code TEXT NOT NULL,
    destination_code TEXT NOT NULL,
    distance_km REAL,
    estimated_duration_min INTEGER,
    airline_id INTEGER,
    is_seasonal INTEGER DEFAULT 0,
    FOREIGN KEY (airline_id) REFERENCES airlines(airline_id)
);

-- Table: flight_legs
CREATE TABLE flight_legs (
    leg_id INTEGER PRIMARY KEY,
    route_id INTEGER NOT NULL,
    aircraft_id INTEGER,
    departure_scheduled TEXT NOT NULL,
    departure_actual TEXT,
    arrival_scheduled TEXT NOT NULL,
    arrival_actual TEXT,
    captain_id INTEGER,
    first_officer_id INTEGER,
    purser_id INTEGER,
    passengers_boarded INTEGER,
    cargo_kg REAL,
    flight_status TEXT CHECK (flight_status IN ('SCHEDULED', 'BOARDING', 'DEPARTED', 'ARRIVED', 'DIVERTED', 'CANCELLED')),
    FOREIGN KEY (route_id) REFERENCES routes(route_id),
    FOREIGN KEY (aircraft_id) REFERENCES fleet(aircraft_id),
    FOREIGN KEY (captain_id) REFERENCES crew(crew_id),
    FOREIGN KEY (first_officer_id) REFERENCES crew(crew_id),
    FOREIGN KEY (purser_id) REFERENCES crew(crew_id)
);

